INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10001, -470, 126401, "クローチェ", "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", 2, 0, 1, 1, "2023/09/22 14:59:59", "2023/06/30 12:00:00", 1.47, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10002, -470, 126401, "クローチェ", "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", 1, 0, 2, 1, "2023/09/22 14:59:59", "2023/06/30 12:00:00", 2.15, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10003, -470, 126501, "ライラエル", "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 2, 0, 2, 1, "2023/09/22 14:59:59", "2023/06/30 12:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10004, -470, 126501, "ライラエル", "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 1, 0, 1, 1, "2023/09/22 14:59:59", "2023/06/30 12:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10005, -470, 127702, "リンド", "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 2, 0, 2, 2, "2023/12/22 14:59:59", "2023/09/15 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10006, -470, 127702, "リンド", "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 2, 0, 2, 2, "2023/12/22 14:59:59", "2023/09/15 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10007, -470, 127802, "ヴルム", "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 1, 0, 1, 2, "2023/12/22 14:59:59", "2023/09/15 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10008, -470, 127802, "ヴルム", "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 1, 0, 2, 2, "2023/12/22 14:59:59", "2023/09/15 15:00:00", 6.5, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10009, -470, 129602, "アネモネ", "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 1, 0, 2, 3, "2024/03/22 14:59:59", "2023/12/15 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10010, -470, 129602, "アネモネ", "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 1, 0, 2, 3, "2024/03/22 14:59:59", "2023/12/15 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10011, -470, 129701, "ネフィ=ネラ", "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 1, 0, 1, 3, "2024/03/22 14:59:59", "2023/12/15 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10012, -470, 129701, "ネフィ=ネラ", "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 1, 0, 2, 3, "2024/03/22 14:59:59", "2023/12/15 15:00:00", 6.2, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10013, -470, 130301, "カノン", "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 5, 0, 3, 4, "2024/06/22 14:59:59", "2024/03/15 15:00:00", 3.1, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10014, -470, 130301, "カノン", "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 2, 0, 3, 4, "2024/06/22 14:59:59", "2024/03/15 15:00:00", 6.15, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10015, -470, 130401, "ナーナ", "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 2, 0, 2, 4, "2024/06/22 14:59:59", "2024/03/15 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10016, -470, 130401, "ナーナ", "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 1, 0, 2, 4, "2024/06/22 14:59:59", "2024/03/15 15:00:00", 3.35, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10017, -470, 130502, "ホウオウ", "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 1, 0, 1, 5, "2024/09/22 14:59:59", "2024/06/15 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10018, -470, 130502, "ホウオウ", "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 1, 0, 2, 5, "2024/09/22 14:59:59", "2024/06/15 15:00:00", 3.18, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (3, 10019, -470, 130503, "ホウオウ", "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 4, 0, 4, 5, "2024/09/22 14:59:59", "2024/06/15 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10020, -470, 123301, "ネア", "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 2, 0, 1, 5, "2024/09/22 14:59:59", "2024/06/15 15:00:00", 4.9, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10021, -470, 123301, "ネア", "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 2, 0, 1, 5, "2024/09/22 14:59:59", "2024/06/15 15:00:00", 4.8, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10022, -470, 133301, "カリザ", "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 1, 0, 3, 6, "2024/12/22 14:59:59", "2024/09/15 15:00:00", 4.922, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10023, -470, 133301, "カリザ", "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 5, 0, 3, 6, "2024/12/22 14:59:59", "2024/09/15 15:00:00", 9.638, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10024, -470, 133401, "ミーア", "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 2, 0, 1, 6, "2024/12/22 14:59:59", "2024/09/15 15:00:00", 2.88, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10025, -470, 133401, "ミーア", "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 1, 0, 5, 6, "2024/12/22 14:59:59", "2024/09/15 15:00:00", 4.818, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10026, -470, 133002, "グレイス", "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 1, 0, 2, 7, "2025/03/22 14:59:59", "2024/12/15 15:00:00", 1.78, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10027, -470, 133002, "グレイス", "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 7, 0, 1, 7, "2025/03/22 14:59:59", "2024/12/15 15:00:00", 6.15, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10028, -470, 133102, "ヴァイオレット", "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 2, 0, 6, 7, "2025/03/22 14:59:59", "2024/12/15 15:00:00", 4.28, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10029, -470, 133102, "ヴァイオレット", "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 1, 0, 1, 7, "2025/03/22 14:59:59", "2024/12/15 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10030, -470, 136902, "ルルィ", "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 1, 0, 2, 8, "2025/06/23 14:59:59", "2025/03/15 15:00:00", 5.53, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10031, -470, 136902, "ルルィ", "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 7, 0, 9, 8, "2025/06/23 14:59:59", "2025/03/15 15:00:00", 6.05, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10032, -470, 137001, "デュラン", "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 1, 0, 2, 8, "2025/06/23 14:59:59", "2025/03/15 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10033, -470, 137001, "デュラン", "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 1, 0, 2, 8, "2025/06/23 14:59:59", "2025/03/15 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10034, -470, 135902, "サツキ", "おう\n好きなもん持ってきな", 2, 0, 2, 9, "2025/09/23 14:59:59", "2025/06/16 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10035, -470, 135902, "サツキ", "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 6, 0, 1, 9, "2025/09/23 14:59:59", "2025/06/16 15:00:00", 4.935, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10036, -470, 135802, "ユキノ", "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 5, 0, 2, 9, "2025/09/23 14:59:59", "2025/06/16 15:00:00", 7.441, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10037, -470, 135802, "ユキノ", "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 7, 0, 7, 9, "2025/09/23 14:59:59", "2025/06/16 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10038, -470, 130901, "クルル", "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 2, 0, 2, 10, "2025/12/22 14:59:59", "2025/09/16 15:00:00", 2.295, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10039, -470, 130901, "クルル", "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 6, 0, 1, 10, "2025/12/22 14:59:59", "2025/09/16 15:00:00", 6.281, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10040, -470, 137701, "ヴォルガーノ", "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 1, 0, 2, 10, "2025/12/22 14:59:59", "2025/09/16 15:00:00", 5.549, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10041, -470, 137701, "ヴォルガーノ", "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 6, 0, 3, 10, "2025/12/22 14:59:59", "2025/09/16 15:00:00", 2.64, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10042, -470, 132801, "ライラエル", "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 4, 0, 7, 11, "2026/03/23 11:59:59", "2025/12/15 15:00:00", 7.642, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10043, -470, 132802, "ライラエル", "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 1, 0, 1, 11, "2026/03/23 11:59:59", "2025/12/15 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10044, -470, 134502, "クローチェ", "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 1, 0, 1, 11, "2026/03/23 11:59:59", "2025/12/15 15:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10045, -470, 134501, "クローチェ", "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 1, 0, 2, 11, "2026/03/23 11:59:59", "2025/12/15 15:00:00", 3.72, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10046, -470, 138201, "ネフィ＝ネラ", "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 1, 0, 2, 12, "2026/06/22 11:59:59", "2026/03/16 12:00:00", 4.991, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10047, -470, 138201, "ネフィ＝ネラ", "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 4, 0, 1, 12, "2026/06/22 11:59:59", "2026/03/16 12:00:00", 3.877, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10048, -470, 136001, "アラクネ", "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 6, 0, 4, 12, "2026/06/22 11:59:59", "2026/03/16 12:00:00", 1.71, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10049, -470, 136001, "アラクネ", "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 2, 0, 5, 12, "2026/06/22 11:59:59", "2026/03/16 12:00:00", 5.32, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10050, -470, 135401, "アネモネ", "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 4, 0, 9, 13, "2026/09/22 11:59:59", "2026/06/15 12:00:00", 3.727, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10051, -470, 135401, "アネモネ", "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 9, 0, 7, 13, "2026/09/22 11:59:59", "2026/06/15 12:00:00", 7.213, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10052, -470, 135301, "クリア", "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 2, 0, 1, 13, "2026/09/22 11:59:59", "2026/06/15 12:00:00", 1.874, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10053, -470, 135301, "クリア", "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", 2, 0, 2, 13, "2026/09/22 11:59:59", "2026/06/15 12:00:00", 0, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 10054, -470, 138001, "ヴァイオレット", "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", 1, 0, 2, 14, "2026/12/22 11:59:59", "2026/09/15 12:00:00", 4.215, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 10055, -470, 138001, "ヴァイオレット", "すみません、わたくしの\n手料理は売り切れなのです\nグレイスが、買い占めを…", 4, 0, 4, 14, "2026/12/22 11:59:59", "2026/09/15 12:00:00", 0, 2002);
